/**
 * Test flow for updateRecord action
 * Demonstrates updating an existing record
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const testUpdateRecord = Flow(
    {
        $id: Now.ID['test_update_record_flow'],
        name: 'Test Update Record',
        description: 'Tests the updateRecord core action',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['test_update_record_trigger'] },
        {
            table: 'incident',
            condition: 'active=true',
            run_flow_in: 'background',
        }
    ),
    (_params) => {
        const result = wfa.action(
            action.core.updateRecord,
            { $id: Now.ID['test_update_record_action'] },
            {
                table_name: 'incident',
                record: wfa.dataPill(_params.trigger.current.sys_id, 'reference'),
                values: TemplateValue({ state: 2, comments: 'Updated by flow' }),
            }
        )

        wfa.action(
            action.core.log,
            { $id: Now.ID['test_update_record_log'] },
            {
                log_level: 'info',
                log_message: `updateRecord outputs: record=${wfa.dataPill(result.record, 'reference')}, table_name=${wfa.dataPill(result.table_name, 'string')}`,
            }
        )
    }
)
